entries[53895] = { ["name"] = "Trank des wahnsinnigen Alchemisten", ["text"] = "Wirken in 3 sek.\nReagenzien:\nGoldklee (2), Magieerfüllte Phiole\n70\nBenötigt Alchemie\n(400)\nBenutzen: Stellt 3100 to 3500 Gesundheit und 4200 to 4400 Mana wieder her. Hat manchmal den Effekt eines weiteren, zufälligen Tranks. (1 Min Abklingzeit)" }
entries[53898] = { ["name"] = "Elixier der mächtigen Seelenstärke", ["text"] = "Wirken in 3 sek.\nReagenzien:\nGoldklee (4), Magieerfüllte Phiole\n70\nBenutzen: Erhöht 1 hour lang die maximale Gesundheit um 350 und stellt alle 5 Sek. 20 Gesundheit wieder her. Wächterelixier. (3 Sek. Abklingzeit)" }
entries[53899] = { ["name"] = "Geringes Fläschchen der Zähigkeit", ["text"] = "Wirken in 3 sek.\nReagenzien:\nBrennnessel (4), Goldklee , Magieerfüllte Phiole\n70\nBenutzen: Erhöht 1 hour lang die Abhärtungswertung um 50. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[53900] = { ["name"] = "Trank der Alpträume", ["text"] = "Wirken in 3 sek.\nReagenzien:\nGoldklee , Talandras Rose (2), Magieerfüllte Phiole\n70\nBenutzen: Lässt den Trinkenden in einen tiefen Schlaf fallen. Im Traum muss er seinen schlimmsten Ängsten ins Auge blicken und sie bezwingen. In dieser Zeit regeneriert er 5400 Gesundheit und Mana, kann sich jedoch nicht verteidigen. (1 Min Abklingzeit)" }
entries[53901] = { ["name"] = "Fläschchen des Frostwyrms", ["text"] = "Wirken in 3 sek.\nReagenzien:\nEisdorn (5), Lichblüte (5), Frostlotus , Verzauberte Phiole\n(2)\n75\nBenutzen: Erhöht die Zaubermacht 1 hour lang um 125. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[53902] = { ["name"] = "Fläschchen des Steinbluts", ["text"] = "Wirken in 3 sek.\nReagenzien:\nLichblüte (7), Kristallisiertes Leben (3), Frostlotus , Verzauberte Phiole\n(2)\n75\nBenutzen: Erhöht 1 hour lang die maximale Gesundheit um 1300. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[53903] = { ["name"] = "Fläschchen der endlosen Wut", ["text"] = "Wirken in 3 sek.\nReagenzien:\nLichblüte (7), Goldklee (3), Frostlotus , Verzauberte Phiole\n(2)\n75\nBenutzen: Erhöht die Angriffskraft 1 hour lang um 180. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[53904] = { ["name"] = "Mächtiger Verjüngungstrank", ["text"] = "Wirken in 3 sek.\nReagenzien:\nTalandras Rose (2), Lichblüte (2), Magieerfüllte Phiole\n70\nBenutzen: Stellt 2475 to 4125 Gesundheit und Mana wieder her. (1 Min Abklingzeit)" }
