entries[54021] = { ["name"] = "Heuschreckenschwarm", ["text"] = "Wirken in 3 sek. 20 sek. Abklingzeit\nAnub'Rekhan verbreitet einen Heuschreckenschwarm. Verlangsamt sein Bewegungstempo um 25% und verursacht bei allen nahen Feinden Schaden. Nahe Feinde können weder angreifen, noch Zauber wirken." }
entries[54022] = { ["name"] = "Heuschreckenschwarm", ["text"] = "Sofort\nDer Heuschreckenschwarm verursacht bei nahen Feinden alle 2 Sek. 875 to 1125 Naturschaden und lässt sie weder angreifen, noch Zauber wirken." }
