entries[54037] = { ["name"] = "Verbesserter Teufelsjäger", ["text"] = "Jedes Mal, wenn Euer Teufelsjäger mit seiner Fähigkeit 'Schattenbiss' trifft, erhält er 4% seines maximalen Manas zurück und die Abklingzeit dieser Fähigkeit wird um 2 Sek. verringert. Zudem wird der Effekt des Zaubers 'Teufelsintelligenz' Eures Teufelsjägers um 5% erhöht." }
entries[54038] = { ["name"] = "Verbesserter Teufelsjäger", ["text"] = "Jedes Mal, wenn Euer Teufelsjäger mit seiner Fähigkeit 'Schattenbiss' trifft, erhält er 8% seines maximalen Manas zurück und die Abklingzeit dieser Fähigkeit wird um 4 Sek. verringert. Der Effekt des Zaubers 'Teufelsintelligenz' Eures Teufelsjägers wird um 10% erhöht." }
entries[54039] = { ["name"] = "Verfluchtes Andenken werfen", ["text"] = "30 Meter Reichweite\nSofort\nWerft das Andenken einem freundlichen Spieler zu. Falls er Platz in seinem Rucksack hat, wird er es fangen!" }
