entries[54043] = { ["name"] = "Aura der Vergeltung", ["text"] = "Sofort\nVerursacht bei jedem Feind, der ein Gruppen- oder Schlachtzugsmitglied schlägt, das sich im Umkreis von 40 Metern befindet, 112 Heiligschaden. Spieler können pro Paladin nur jeweils eine Aura besitzen." }
