entries[54998] = { ["name"] = "Handmontierte Pyrorakete", ["text"] = "Wirken in 5 sek.\nBenötigt Handschuhe\nTools:\nBogenlichtschraubenschlüssel\nReagenzien:\nSaronitbarren (6), Kristallisiertes Feuer (4)\nBringt an einem Paar Handschuhe dauerhaft einen Pyroraketenwerfer an, der es einem geschickten Ingenieur gestattet, eine Rakete abzuschießen, die auf Distanz 1654 to 2020 Feuerschaden verursacht. Kann nur einmal alle 45 Sek. abgefeuert werden.\n\nKann nur an Eure eigenen Handschuhe angebracht werden und sie werden dadurch seelengebunden." }
entries[54999] = { ["name"] = "Hypergeschwindigkeitsbeschleuniger", ["text"] = "Wirken in 5 sek.\nBenötigt Handschuhe\nTools:\nBogenlichtschraubenschlüssel\nReagenzien:\nSaronitbarren (6), Kristallisierte Luft (4)\nBringt an einem Paar Handschuhe dauerhaft Hypergeschwindigkeitsbeschleuniger an, die es einem geschickten Ingenieur gestatten, seine Tempowertung 12 sec lang um 340 zu erhöhen. Die Handschuhe können nur einmal pro Minute aktiviert werden." }
